# Let's look for strings in the binary that might give us hints
# about what input format is expected

import angr

proj = angr.Project('{TARGET}', auto_load_libs=False)

# Look for strings in the binary
strings = []
for section in proj.loader.main_object.sections:
    if section.is_readable:
        try:
            data = proj.loader.memory.load(section.min_addr, section.max_addr - section.min_addr)
            # Find printable strings
            current_str = b''
            current_addr = section.min_addr
            for i, b in enumerate(data):
                if 0x20 <= b <= 0x7e:
                    current_str += bytes([b])
                else:
                    if len(current_str) >= 6:
                        strings.append((current_addr + i - len(current_str), current_str))
                    current_str = b''
            if len(current_str) >= 6:
                strings.append((current_addr + len(data) - len(current_str), current_str))
        except Exception as e:
            pass

# Filter for interesting strings
interesting_keywords = ['usage', 'flag', 'pass', 'key', 'secret', 'correct', 'wrong', 
                         'valid', 'invalid', 'accept', 'reject', 'error', 'success',
                         'check', 'input', 'wasm', 'chall', 'func', 'module', 'invoke']

print("Interesting strings found:")
for addr, s in strings:
    try:
        decoded = s.decode('ascii', errors='ignore')
        if any(kw in decoded.lower() for kw in interesting_keywords):
            print(f"  {hex(addr)}: {decoded[:120]}")
    except:
        pass
